Rules.InvariantScript:
If(
    !IsBlank(varCurrentSetup.'Id (ID)'),
    Set(varCurrentSetup, LookUp(Equipment_Setups, 'Id (ID)' = varCurrentSetup.'Id (ID)'))
);
Set(
    varSetupFields,
    Table(
        { FieldName: "Name",              FieldValue: Coalesce(varCurrentSetup.SetupName, "-") },
        { FieldName: "Campus",            FieldValue: Coalesce(varCurrentSetup.CurrentCampus.Value, "-") },
        { FieldName: "Room",            FieldValue: Coalesce(varCurrentSetup.CurrentLocation.Value, "-") },
        { FieldName: "Responsible person", FieldValue: Coalesce(varCurrentSetup.ResponsiblePerson.DisplayName, "-") },
        { FieldName: "Description",      FieldValue: Coalesce(varCurrentSetup.Description, "-") },
{ FieldName: "Commissioning required", FieldValue: Coalesce(varCurrentSetup.CommissioningRequired.Value, "-") },
{ FieldName: "Commissioning done",     FieldValue: If(
    IsEmpty(varCurrentSetup.CommissioningDone),
    "-",
    Concat(varCurrentSetup.CommissioningDone, Value, ", ")
) }
    )
)

With(
    {
        req: Coalesce(varCurrentSetup.CommissioningRequired.Value, "None"),
        done: Concat(varCurrentSetup.CommissioningDone, Value, " | ")
    },
    If(
        req = "None",                       "Not required",
        // Commissioned at this campus, among possibly several.
        !IsBlank(Find(req, done)),          "Commissioned",
        // An extended commissioning covers the administrative one.
        req = "administrative"
            && !IsBlank(Find("extended", done)),
                                            "Commissioned",
        IsBlank(done),                      "Not commissioned",
        // Something was done, but not what this asset needs.
        "Incomplete"
    )
)

With(
    {
        req: Coalesce(varCurrentSetup.CommissioningRequired.Value, "None"),
        done: Concat(varCurrentSetup.CommissioningDone, Value, " | ")
    },
    If(
        req = "None",                       RGBA(16, 124, 16, 1),
        // Commissioned at this campus, among possibly several.
        !IsBlank(Find(req, done)),          RGBA(16, 124, 16, 1),
        // An extended commissioning covers the administrative one.
        req = "administrative"
            && !IsBlank(Find("extended", done)),
                                            RGBA(16, 124, 16, 1),
        IsBlank(done),                      RGBA(168, 0, 0, 1),
        // Something was done, but not what this asset needs.
        RGBA(196, 116, 0, 1)
    )
)

Max(
    CountRows(
        Filter(Equipment_Assets, varCurrentSetup.Titel in Setups.Value)
    ),
    1
) * If(Parent.Width < 600, 94, 56)

If(
    IsBlank(LookUp(colSetupAddPick, Value = ThisItem.Titel)),
    Collect(
        colSetupAddPick,
        { Id: ThisItem.'Id (ID)', Value: ThisItem.Titel }
    )
);
Reset(txtSetupAddSearch)

If(
    IsBlank(LookUp(colSetupAddPick, Value = ThisItem.Titel)),
    Collect(
        colSetupAddPick,
        { Id: ThisItem.'Id (ID)', Value: ThisItem.Titel }
    )
);
Reset(txtSetupAddSearch)

If(
    IsBlank(LookUp(colSetupAddPick, Value = ThisItem.Titel)),
    Collect(
        colSetupAddPick,
        { Id: ThisItem.'Id (ID)', Value: ThisItem.Titel }
    )
);
Reset(txtSetupAddSearch)

ForAll(
    colSetupAddPick As p,
    // An asset already in this setup is skipped rather than written in twice.
    If(
        IsBlank(
            LookUp(LookUp(Equipment_Assets, 'Id (ID)' = p.Id).Setups, Value = varCurrentSetup.Titel)
        ),
        Patch(
            Equipment_Assets,
            LookUp(Equipment_Assets, 'Id (ID)' = p.Id),
            {
                // The asset keeps the setups it already had, with this one added.
                // Two tables are joined by wrapping each in a record and ungrouping
                // them - a table has no append.
                Setups: Ungroup(
                    Table(
                        { part: ForAll(
                            LookUp(Equipment_Assets, 'Id (ID)' = p.Id).Setups As e,
                            { '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedReference", Id: e.Id, Value: e.Value }
                        ) },
                        { part: Table(
                            { '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedReference", Id: varCurrentSetup.'Id (ID)', Value: varCurrentSetup.Titel }
                        ) }
                    ),
                    part
                )
            }
        )
    )
);
If(
    IsEmpty(Errors(Equipment_Assets)),
    Notify(
        CountRows(colSetupAddPick) & " asset(s) added to " & varCurrentSetup.Titel & ".",
        NotificationType.Success
    );
    Clear(colSetupAddPick),
    Notify(
        "Could not add them: " & Concat(Errors(Equipment_Assets), Message, " | "),
        NotificationType.Error
    )
)

Set(
    varSetupNew,
    Filter(
        Filter(Equipment_Assets, varCurrentSetup.Titel in Setups.Value),
        Not('Id (ID)' in colMoveBuffer.'Id (ID)')
    )
);
Collect(colMoveBuffer, varSetupNew);
Notify(
    CountRows(varSetupNew) & " asset(s) added to the move list.",
    NotificationType.Success
);
Navigate(scr_Move, ScreenTransition.Fade)

Patch(
    Equipment_Assets,
    LookUp(Equipment_Assets, 'Id (ID)' = varRemoveFromSetup.'Id (ID)'),
    {
        // Write back the asset's other setups, without this one.
        // ForAll keeps the table's schema when the result is empty,
        // which is what clears the last setup.
        Setups: ForAll(
            Filter(
                varRemoveFromSetup.Setups,
                Value <> varCurrentSetup.Titel
            ) As s,
            {
                '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedReference",
                Id: s.Id,
                Value: s.Value
            }
        )
    }
);
If(
    IsEmpty(Errors(Equipment_Assets)),
    Notify(
        varRemoveFromSetup.Titel & " removed from this setup.",
        NotificationType.Success
    ),
    Notify(
        "Could not remove it: " &
            Concat(Errors(Equipment_Assets), Message, " | "),
        NotificationType.Error
    )
);
Set(varRemoveFromSetup, Blank())
